CREATE TABLE Consumer (
    Address_Information VARCHAR(255),
    Consumer_ID INTEGER PRIMARY KEY,
    Phone_Number VARCHAR(255)
);

CREATE TABLE Courier_Company (
    Arrival_Time DATETIME,
    Charging_Price FLOAT,
    Company_Name VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Courier_Tracking (
    Courier_Tracking_Number VARCHAR(255) PRIMARY KEY,
    Recipient_ID INTEGER,
    Recipient_Name VARCHAR(255),
    Recipient_Phone_Number VARCHAR(255)
);

CREATE TABLE Administrator (
    Administrator_ID INTEGER PRIMARY KEY,
    Courier_Username VARCHAR(255),
    Login_Password VARCHAR(255),
    Name VARCHAR(255)
);

CREATE TABLE Cooperation (
    Administrator_ID INTEGER NOT NULL,
    Company_Name VARCHAR(255) NOT NULL,
    PRIMARY KEY (Company_Name, Administrator_ID),
    FOREIGN KEY (Administrator_ID) REFERENCES Administrator(Administrator_ID),
    FOREIGN KEY (Company_Name) REFERENCES Courier_Company(Company_Name)
);
